# Flow bands use source and branch anchors; nested split is a second independent column.
sankey='''@{'''+base+text+'''display:flex;flex-direction:column;padding:var(--gap-sm) 24% var(--gap-sm) 48%;gap:var(--gap-sm);anchor-scope:all;isolation:isolate;transform:translate(0)} @ .source{box-sizing:border-box;position:absolute;left:0;top:20%;width:20%;height:60%;display:flex;flex-direction:column;align-items:center;justify-content:center;background:var(--a1-7);color:var(--page);padding:var(--gap-sm);text-align:center;anchor-name:--crossrail-flow-source} @ .source .name{margin:0;font-size:var(--type-20);font-weight:var(--name-weight);line-height:var(--name-line)} @ .source .fig{margin:var(--gap-sm) 0 0;font-size:var(--type-32);font-weight:var(--figure-weight);line-height:var(--figure-line)} @>.branch{position:relative;box-sizing:border-box;flex:var(--v) 1 0;min-height:0;display:flex;flex-direction:column;align-items:center;justify-content:center;background:var(--n-3);color:var(--ink);padding:calc(var(--gap-sm)/2);text-align:center} @>.branch.on{background:var(--a1-7);color:var(--page)} @>.branch.out{background:var(--n-2);color:var(--n-7)} @ .branch>.name{margin:0;font-size:var(--type-18);font-weight:var(--name-weight);line-height:var(--name-line)} @ .branch>.fig{margin:calc(var(--gap-sm)/3) 0 0;font-size:var(--type-22);font-weight:var(--figure-weight);line-height:var(--figure-line)} @>.branch::before{content:"";position:fixed;left:20cqw;right:52cqw;top:0;bottom:0;background:var(--n-3);clip-path:polygon(0 calc(50% - 30%*var(--v)/100),100% anchor(var(--crossrail-branch-anchor) top),100% anchor(var(--crossrail-branch-anchor) bottom),0 calc(50% + 30%*var(--v)/100));z-index:-1} @>.branch.on::before{background:var(--a1-7)} @>.branch.out::before{background:var(--n-2)} @ .branch>.branch{position:absolute;left:calc(100% + 10cqw);top:0;width:18cqw;height:calc(var(--v)*1%);display:flex;flex-direction:column;align-items:center;justify-content:center;box-sizing:border-box;padding:calc(var(--gap-sm)/3);background:var(--n-3);color:var(--ink);border-left:2px solid var(--n-5)} @ .branch>.branch:nth-child(2 of .branch){top:auto;bottom:0} @ .branch>.branch:nth-child(3 of .branch){top:33%} @ .branch>.branch:nth-child(4 of .branch){top:66%} @ .branch>.branch::before{content:"";position:absolute;right:100%;top:50%;width:10cqw;border-top:1px solid var(--n-4)} @container(max-width:850px){@ .source .name,@ .branch>.name{font-size:var(--type-14)} @ .source .fig,@ .branch>.fig{font-size:var(--type-18)}}'''
